CREATE TABLE livestock_sales (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, animal_id BIGINT UNSIGNED NOT NULL, financial_transaction_id BIGINT UNSIGNED NULL, sale_date DATE NOT NULL, buyer_name VARCHAR(200) NULL, amount DECIMAL(15,2) NOT NULL, payment_status ENUM('pending','paid','cancelled') NOT NULL DEFAULT 'pending', notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_livestock_sales_ft (financial_transaction_id), KEY idx_livestock_sales_date (sale_date), CONSTRAINT chk_livestock_sales_amount CHECK (amount > 0), CONSTRAINT fk_ls_animal FOREIGN KEY (animal_id) REFERENCES animals(id) ON DELETE RESTRICT, CONSTRAINT fk_ls_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
